<script setup lang="ts">
import{onMounted,ref,watch}from'vue';import{storeToRefs}from'pinia';import{RouterLink,useRoute,useRouter}from'vue-router';import ProcurementSubnav from'../components/ProcurementSubnav.vue';import ProcurementScenarioBar from'../components/ProcurementScenarioBar.vue';import{useProcurementStore}from'../runtime/procurement-store';import{parseSupplierCsv,supplierCsvTemplate}from'../services/procurement-csv';import type{SupplierImportPreview}from'../types';import'./procurement-views.css';const store=useProcurementStore(),route=useRoute(),router=useRouter();const{workspace,loading,error,scenario,actor,saving,canWrite}=storeToRefs(store);const keyword=ref(String(route.query.keyword??'')),skuKeyword=ref(String(route.query.sku??'')),status=ref((route.query.status as 'all'|'enabled'|'disabled')??'all'),showImport=ref(false),csv=ref(supplierCsvTemplate()),parseErrors=ref<string[]>([]),preview=ref<SupplierImportPreview|null>(null);let syncing=false
async function search(){await router.replace({query:{...(keyword.value&&{keyword:keyword.value}),...(skuKeyword.value&&{sku:skuKeyword.value}),...(status.value!=='all'&&{status:status.value})}});await store.applySupplierQuery({keyword:keyword.value,skuKeyword:skuKeyword.value,status:status.value,page:1,pageSize:30})}function download(name:string,content:string){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\uFEFF',content],{type:'text/csv;charset=utf-8'}));link.download=name;link.click();URL.revokeObjectURL(link.href)}function previewCsv(){const parsed=parseSupplierCsv(csv.value);parseErrors.value=parsed.errors;preview.value=parsed.errors.length?null:store.previewImport(parsed.rows)}async function commitImport(){if(!preview.value?.valid)return;await store.importSuppliers(preview.value);showImport.value=false;preview.value=null}watch(()=>route.query,async()=>{if(syncing)return},{deep:true});onMounted(()=>search())
</script>
<template><section class="procurement-page"><header class="procurement-header"><div><h1>供应商管理</h1><p>维护供应商主数据、供货能力与启停状态；账号凭据未接入。</p></div><ProcurementScenarioBar :scenario="scenario" :role="actor.role" @scenario="store.setScenario" @role="store.setRole"/></header><ProcurementSubnav/><form class="procurement-toolbar" @submit.prevent="search"><label class="grow">名称 / 编码 / 联系人 / 电话<input v-model="keyword" type="search" placeholder="输入关键字"></label><label class="grow">供货商品<input v-model="skuKeyword" type="search" placeholder="商品、SKU、规格或条码"></label><label>状态<select v-model="status"><option value="all">全部</option><option value="enabled">启用</option><option value="disabled">停用</option></select></label><button class="pur-button" type="submit">查询</button><div class="actions"><button v-if="canWrite" class="pur-button" type="button" @click="showImport=true">导入</button><button class="pur-button" type="button" @click="download('供应商.csv',store.exportSuppliers())">导出</button><RouterLink v-if="canWrite" class="pur-button primary" to="/procurement/suppliers/new">新增供应商</RouterLink></div></form><div v-if="error" class="procurement-state error" role="alert">{{error}}<button class="pur-button" @click="store.load">重试</button></div><div v-else-if="loading" class="procurement-state">正在加载供应商…</div><div v-else-if="!workspace.suppliers.total" class="procurement-state"><strong>暂无供应商</strong><span>可以调整筛选或新增供应商。</span></div><template v-else><div class="procurement-table-wrap"><table class="procurement-table"><thead><tr><th>供应商</th><th>类型 / 供货方式</th><th>联系人</th><th>启用供货商品</th><th>状态</th><th>账号</th><th>地址</th><th>操作</th></tr></thead><tbody><tr v-for="row in workspace.suppliers.items" :key="row.id"><td><RouterLink :to="`/procurement/suppliers/${row.id}`"><strong>{{row.name}}</strong></RouterLink><small>{{row.code}}</small></td><td>{{row.tradeType==='purchase'?'购销':'代销'}}<small>{{({warehouse:'入仓',direct:'直送',both:'均可'} as const)[row.deliveryMode]}}</small></td><td>{{row.contactName}}<small>{{row.contactPhone}}</small></td><td>{{row.enabledProductCount}}</td><td><span class="pur-status" :class="row.status">{{row.status==='enabled'?'启用':'停用'}}</span></td><td><span class="pur-status unavailable">未接入</span></td><td>{{row.address??'—'}}</td><td><RouterLink :to="`/procurement/suppliers/${row.id}`">详情</RouterLink> · <RouterLink v-if="canWrite" :to="`/procurement/suppliers/${row.id}/edit`">编辑</RouterLink></td></tr></tbody></table></div><div class="procurement-pagination">共 {{workspace.suppliers.total}} 条 · 第 {{workspace.suppliers.page}} 页</div></template><div v-if="showImport" class="procurement-dialog" role="dialog" aria-modal="true"><section><header><strong>供应商 CSV 导入预览</strong><button class="pur-button" @click="showImport=false">关闭</button></header><div class="procurement-panel"><p class="procurement-warning">原型模拟：UTF-8 CSV 只写入浏览器内 Mock；任一行错误会整批拒绝。</p><textarea v-model="csv" aria-label="CSV 内容"></textarea><p v-for="item in parseErrors" :key="item" class="procurement-warning">{{item}}</p><p v-for="item in preview?.issues" :key="`${item.rowNumber}-${item.field}`" class="procurement-warning">第 {{item.rowNumber}} 行 {{item.field}}：{{item.message}}</p><p v-if="preview?.valid">校验通过：{{preview.rows.length}} 行可导入。</p><div class="procurement-actions"><button class="pur-button" @click="previewCsv">预览校验</button><button class="pur-button primary" :disabled="!preview?.valid||saving" @click="commitImport">确认导入</button></div></div></section></div></section></template>
